//! Test-facing names for the cycle model generated by [`crate::core`]:
//! nibble-level MII types and a configuration with plain integers.
use crate::consts::*;
use crate::core::eth_core;
use crate::proto::ProtoConfig;
use crate::rx::MiiRx;
use bitlogic::bits;

pub use bitlogic::{Evaluate as Steps, Interpreted, Native};

/// The generated cycle model of `eth_core`.
pub type EthCore<S = Native> = eth_core::Core<S>;

/// One MII nibble cycle on the receive side.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RxNibble {
    pub dv: bool,
    pub rxd: u8,
    pub rxerr: bool,
}

impl From<RxNibble> for eth_core::Inputs {
    fn from(n: RxNibble) -> Self {
        Self {
            mii: MiiRx {
                dv: n.dv,
                rxd: bits(n.rxd.into()),
                rxerr: n.rxerr,
            },
        }
    }
}

/// The registered MII transmit outputs after a clock edge.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct TxNibble {
    pub en: bool,
    pub txd: u8,
}

impl From<eth_core::Outputs> for TxNibble {
    fn from(o: eth_core::Outputs) -> Self {
        Self {
            en: o.tx_en,
            txd: o.txd.get() as u8,
        }
    }
}

/// Parameters of `eth_core`; tests shorten the timer intervals.
#[derive(Clone, Copy, Debug)]
pub struct CoreConfig {
    pub mac: u64,
    pub ip: u32,
    pub beacon_interval: u32,
    pub garp_interval: u32,
    pub feed_ip: u32,
    pub feed_port: u16,
    pub bbo_mac: u64,
}

impl Default for CoreConfig {
    fn default() -> Self {
        Self {
            mac: FPGA_MAC,
            ip: FPGA_IP,
            beacon_interval: BEACON_INTERVAL_CYCLES,
            garp_interval: GRATUITOUS_ARP_INTERVAL_CYCLES,
            feed_ip: FEED_GROUP_IP,
            feed_port: FEED_PORT,
            bbo_mac: BBO_MAC,
        }
    }
}

impl From<CoreConfig> for ProtoConfig {
    fn from(c: CoreConfig) -> Self {
        Self {
            mac: bits(c.mac),
            ip: bits(c.ip.into()),
            beacon_interval: bits(c.beacon_interval.into()),
            garp_interval: bits(c.garp_interval.into()),
            feed_ip: bits(c.feed_ip.into()),
            feed_port: bits(c.feed_port.into()),
            bbo_mac: bits(c.bbo_mac),
        }
    }
}
